/**
 * bandd_playtest 二合一模组的**版本无关 core**（9 个 Java 类）—— 2026-11-03 回填。
 *
 * 来源：`F:\B AND D MOD\mod\shared\core\com\bandd\playtest\core\`（四档真机验证过的同一份）。
 * 架构：`HttpApi`（HTTP 线程**只入队**，绝不碰 MC）→ `ActionQueue` → `PlaytestCore.onTick()`（客户端 tick 线程）
 * → `GameBridge`（**唯一**与平台相关的接口）→ 各档适配层。外加 `EvidenceWriter`（state.json/exit-code.txt/qa.log/rounds.jsonl）
 * 与 `Arbitration`（AUTO/HOTKEY/DUAL）。
 *
 * ⚠ **真机教训（勿重踩）**：
 *   - `GameBridge.unavailableActions()` 的 default 返回**空**会让 `/status` 谎报能力 ⇒ 各档必须**按实际做得到的列白名单**；
 *   - **reobf 不改反射字符串** ⇒ core/适配层**禁止**反射访问 MC（生成器已有 `assertNoReflectiveMcAccess` 守）；
 *   - HTTP 端口是**动态**的（`HttpApi.start()` 从首选端口往后试 20 个）⇒ 消费方必须实时解析（读 qa.log 的
 *     `[QA] http listening on 127.0.0.1:<port>` 或探活）。
 *
 * 用法：`PLAYTEST_MOD_CORE_SOURCES` 是「相对路径 → 源码」的表，生成器按需落到 `playtest/core/`。
 */
export const PLAYTEST_MOD_CORE_SOURCES: Readonly<Record<string, string>> = {
  "playtest/core/com/bandd/playtest/core/ActionQueue.java": "package com.bandd.playtest.core;\n\nimport java.util.Map;\nimport java.util.Queue;\nimport java.util.concurrent.CompletableFuture;\nimport java.util.concurrent.ConcurrentLinkedQueue;\nimport java.util.concurrent.TimeUnit;\n\n/**\n * 动作队列。**线程纪律（照抄仓库口径，playtest-bridge-mod.ts:38）**：\n * HTTP 处理线程**只入队**，一切 MC 调用都在客户端 tick 线程执行（HTTP 线程碰 MC 会崩）。\n */\npublic final class ActionQueue {\n    private final Queue<Job> q = new ConcurrentLinkedQueue<>();\n\n    public Job submit(String action, Map<String, Object> params) {\n        Job j = new Job(action, params);\n        q.add(j);\n        return j;\n    }\n\n    /** 客户端 tick 里调用：在本线程（= MC 线程）执行所有排队动作。 */\n    public void drain(PlaytestCore core) {\n        Job j;\n        while ((j = q.poll()) != null) {\n            j.run(core);\n        }\n    }\n\n    public static final class Job {\n        private final String action;\n        private final Map<String, Object> params;\n        private final CompletableFuture<Map<String, Object>> fut = new CompletableFuture<>();\n\n        Job(String action, Map<String, Object> params) {\n            this.action = action;\n            this.params = params;\n        }\n\n        public String action() { return action; }\n\n        public Map<String, Object> params() { return params; }\n\n        void run(PlaytestCore core) {\n            try {\n                fut.complete(core.dispatch(action, params));\n            } catch (Throwable t) {\n                fut.complete(PlaytestCore.error(\"EXEC_FAILED\", String.valueOf(t)));\n            }\n        }\n\n        /** HTTP 线程在这里等 tick 线程的结果；超时返回 null（= 不静默，报 TIMEOUT）。 */\n        public Map<String, Object> await(long ms) {\n            try {\n                return fut.get(ms, TimeUnit.MILLISECONDS);\n            } catch (Exception e) {\n                return null;\n            }\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/Arbitration.java": "package com.bandd.playtest.core;\n\nimport java.util.LinkedHashSet;\nimport java.util.Set;\n\n/**\n * 输入仲裁。**用户裁定：做成模组选项，由玩家运行时选**，所以三种模式全部实现。\n *\n *  AUTO   真人一按「AI 没按过的键」→ AI 让位（暂停 + 释放自己按过的键）\n *  HOTKEY 显式切换持权方（HTTP take_over / 游戏内热键）\n *  DUAL   AI 不碰按键（只用桥面命令）⇒ 不抢方向盘\n *\n * **记账式释放**：只释放「AI 自己按下过的键」，绝不无差别清空\n * （仓库 driver 的 releaseAll 会连带清掉真人的键 —— 见 reference/generators/playtest-driver.ts:4582-4589，\n *  那是\"一起玩\"下的真 bug，本模组不照抄）。\n */\npublic final class Arbitration {\n    public enum Mode { AUTO, HOTKEY, DUAL }\n\n    private Mode mode = Mode.AUTO;\n    private boolean aiOwns = true;\n    private final Set<String> owned = new LinkedHashSet<>();\n    private int yields = 0;\n    private String lastReason = \"init\";\n\n    public synchronized Mode mode() { return mode; }\n\n    public synchronized void setMode(Mode m) {\n        mode = m;\n        lastReason = \"mode=\" + m;\n        if (m == Mode.DUAL) { aiOwns = false; }\n        if (m == Mode.AUTO) { aiOwns = true; }\n    }\n\n    public synchronized boolean aiOwns() { return aiOwns; }\n\n    public synchronized int yields() { return yields; }\n\n    public synchronized String lastReason() { return lastReason; }\n\n    public synchronized boolean isOwned(String key) { return owned.contains(key); }\n\n    /** 真人是否在按一个「AI 没按过」的键（AUTO 让位判据）。 */\n    public synchronized boolean humanHasControl(GameBridge bridge) {\n        for (String k : bridge.supportedKeys()) {\n            if (!owned.contains(k) && bridge.isPressed(k)) return true;\n        }\n        return false;\n    }\n\n    public synchronized void yieldToHuman(GameBridge bridge, String reason) {\n        aiOwns = false;\n        yields++;\n        lastReason = reason;\n        releaseOwned(bridge);\n    }\n\n    public synchronized void takeOver() {\n        aiOwns = true;\n        lastReason = \"ai takeover\";\n    }\n\n    /** 只释放 AI 自己按下的键。 */\n    public synchronized void releaseOwned(GameBridge bridge) {\n        for (String k : new LinkedHashSet<>(owned)) {\n            bridge.setPressed(k, false);\n        }\n        owned.clear();\n    }\n\n    public synchronized void noteOwned(String key, boolean down) {\n        if (down) owned.add(key); else owned.remove(key);\n    }\n\n    public synchronized int ownedCount() { return owned.size(); }\n}\n",
  "playtest/core/com/bandd/playtest/core/Capabilities.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n/** 能力自报：/status 里如实报「本档这一份 JAR 到底能做什么」，缺的面明确报 unavailable，不静默。 */\npublic final class Capabilities {\n    /** 桥面 = 命令级。 */\n    public static final List<String> BRIDGE = Arrays.asList(\n            \"ping\", \"query_player_state\", \"query_screen\", \"screenshot\", \"chat_command\",\n            \"set_arbitration\", \"status\",\n            \"query_chat\", \"chat_say\");   // 聊天桥：读玩家打的字 / 以 [AI] 身份回话\n    /** driver 面 = 玩家级（真按键）。 */\n    public static final List<String> DRIVER = Arrays.asList(\n            \"press\", \"release_all\", \"take_over\", \"open_world\", \"look\",\n            \"spawn_bot\", \"bot_move\", \"bot_follow\", \"bot_despawn\", \"open_bot_inventory\",\n            \"bot_give\", \"bot_look\", \"bot_break\", \"bot_place\", \"join_server\", \"set_auth\");\n\n    private Capabilities() {}\n\n    public static List<String> all() {\n        List<String> l = new ArrayList<>(BRIDGE);\n        l.addAll(DRIVER);\n        return l;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/EvidenceWriter.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.nio.file.StandardOpenOption;\nimport java.time.Instant;\n\n/**\n * 证据三件：state.json / exit-code.txt / qa.log。\n * 口径与仓库一致：**缺件读作 absent，不得读成\"没有失败\"**（fail-closed）。\n */\npublic final class EvidenceWriter {\n    private final Path dir;\n\n    public EvidenceWriter(Path dir) { this.dir = dir; }\n\n    public Path dir() { return dir; }\n\n    public void log(String line) {\n        append(\"qa.log\", \"[\" + Instant.now() + \"] \" + line + \"\\n\");\n    }\n\n    public void state(String json) {\n        write(\"state.json\", json);\n    }\n\n    public void exitCode(int code) {\n        write(\"exit-code.txt\", code + \"\\n\");\n    }\n\n    /** 铁律 2：qa.log 只含本轮 => 轮首截断。 */\n    public void truncateQaLog() {\n        write(\"qa.log\", \"\");\n    }\n\n    /** 每轮一行（含 ok）。 */\n    public void appendRounds(String jsonLine) {\n        append(\"rounds.jsonl\", jsonLine + \"\\n\");\n    }\n\n    private void append(String name, String text) {\n        try {\n            Files.createDirectories(dir);\n            Files.write(dir.resolve(name), text.getBytes(StandardCharsets.UTF_8),\n                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);\n        } catch (IOException e) {\n            // 证据写不进去不静默：打到 stdout 让日志面看得见\n            System.err.println(\"[bandd-playtest] evidence append failed: \" + e);\n        }\n    }\n\n    private void write(String name, String text) {\n        try {\n            Files.createDirectories(dir);\n            Files.write(dir.resolve(name), text.getBytes(StandardCharsets.UTF_8),\n                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);\n        } catch (IOException e) {\n            System.err.println(\"[bandd-playtest] evidence write failed: \" + e);\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/GameBridge.java": "package com.bandd.playtest.core;\n\n/**\n * core ↔ 逐档适配层 的唯一接口。**core 里不许出现任何 net.minecraft.* / 加载器类型**\n * （这样同一份 core 源码可以喂给每个 (加载器, MC 版本) 的 adapter）。\n */\npublic interface GameBridge {\n    String platform();\n\n    String mcVersion();\n\n    /** 玩家与世界都在场（桥协议里的 ready）。 */\n    boolean ready();\n\n    /** 客户端 tick 调用一次（core 的队列在这里排空）。 */\n    void tick();\n\n    /** 玩家/世界读数（JSON 片段字符串）。 */\n    String playerStateJson();\n\n    /** 当前打开的界面名；无界面返回 null。 */\n    String screenName();\n\n    /** 截图，返回落盘路径。 */\n    String screenshotPath();\n\n    /**\n     * 召唤**可见的**化身（第二个角色）。\n     * 返回载体名（如 \"fake_player\" / \"mannequin\"）；本档或当前环境不支持则返回 null。\n     */\n    String spawnBot(String name, double distance);\n\n    /** 把化身移到绝对坐标（可见性由适配层负责，core 不碰 MC）。 */\n    void moveBotTo(double x, double y, double z);\n\n    /**\n     * 每个客户端 tick 驱动一次化身（core 调用）。\n     * 为什么需要：**FakePlayer.tick() 是 NeoForge 置空的**（字节码只有 `return`）⇒ 玩家自身的\n     * 捡拾/物理逻辑永不运行；这一钩子用来显式补上（如把附近掉落物喂给它）。\n     */\n    void tickBot();\n\n    // ---- 化身的\"玩家功能\"（服务端 ServerPlayerGameMode 面；形状复用仓库已核实的 driver 调用）----\n    /** 给化身发物品。item = \"minecraft:diamond\" 这类 id；失败返回 null。 */\n    String giveBot(String item, int count);\n\n    /** 把化身转向（yaw/pitch，MC 约定）。 */\n    boolean lookBot(double yaw, double pitch);\n\n    /** 化身挖掉一个方块（创造模式即时；对应仓库 driver 的 destroyBlock 口径）。 */\n    String breakBotBlock(double x, double y, double z);\n\n    /** 化身用手上的方块对着目标放（对应仓库 driver 的 useItemOn 口径）。 */\n    String placeBotBlock(double x, double y, double z);\n\n    /**\n     * 开关**本机服务端**的会话认证（只对单人/局域网世界有意义）。\n     * 为什么需要：集成服务器在构造里**强制** usesAuthentication(true)（字节码 iconst_1 实证），\n     * 而开发环境的第二客户端是**离线会话** ⇒ 必然 \"Invalid session\"。关掉它，离线客户端才能进。\n     */\n    boolean setServerAuth(boolean online);\n\n    /** 作为**真客户端**连到一个服务器/局域网世界（第二客户端路线的入口）。 */\n    void joinServer(String address);\n\n    /** 收回化身。 */\n    void despawnBot();\n\n    /**\n     * 把**化身的物品栏**开到**真人**的屏幕上（假玩家自己开不了 GUI —— openMenu 被 NeoForge 写成空实现）。\n     * 返回载体说明；不支持则 null。\n     */\n    String openBotInventory();\n\n    /**\n     * 取走**新收到**的聊天（自上次调用以来），并清空缓冲。\n     * 适配层负责挂聊天事件；core 只做搬运与暴露。\n     */\n    java.util.List<String> drainChat();\n\n    /** 进入/加载一个世界（driver 面：AI 或玩家都可用）。 */\n    void openWorld(String worldName);\n\n    /** 以玩家身份发一条命令（命令级动作）。 */\n    void chatCommand(String command);\n\n    /** 读**真人**是否正按着这个逻辑键（仲裁用）。 */\n    boolean isPressed(String key);\n\n    /** 写按键（玩家级动作）。 */\n    void setPressed(String key, boolean down);\n\n    /** 该档支持哪些逻辑键。 */\n    java.util.List<String> supportedKeys();\n\n    /**\n     * **本档做不了**的动作名（供 /status 如实自报）。默认空 = 全都做得了。\n     *\n     * 为什么需要它：`PlaytestCore.status()` 原本**无条件**报 `Capabilities.all()` ⇒ 一个 MC 侧\n     * 全 fail-closed 的档（如 ModLoader 三档：玩家/位置/截图/读方块/按键都没有出处）会在\n     * `/status` 里**谎报**自己会按按键、会截图 —— 而 `/execute` 实际一律失败。\n     * 「能力自报」谎报比没有自报更糟：调用方会据此排计划。\n     *\n     * Java 8 default 方法 ⇒ **现有适配层一行都不用改**（不实现 = 空 = 行为与从前完全一致）。\n     * 动作名取自 {@link Capabilities}。\n     */\n    /**\n     * **本机玩家**转视角（不是化身）—— `bot_look` 是给假玩家化身的，真客户端的「身体」就是 `mc.player` 自己。\n     *\n     * Java 8 default 方法 ⇒ **现有适配层一行都不用改**（不实现 = false = 行为与从前完全一致，\n     * 且 `/status` 会把它列进 `actionsUnavailable`）。\n     *\n     * 语义：设玩家朝向（yaw ∈ [-180,180]，pitch ∈ [-90,90]）。真客户端里设完由客户端 tick\n     * 自行把朝向发出去（多人/局域网时服务端看得到）。\n     */\n    default boolean look(double yaw, double pitch) {\n        return false;\n    }\n\n    default java.util.List<String> unavailableActions() {\n        return java.util.Collections.emptyList();\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/HttpApi.java": "package com.bandd.playtest.core;\n\nimport com.sun.net.httpserver.HttpExchange;\nimport com.sun.net.httpserver.HttpServer;\n\nimport java.io.IOException;\nimport java.io.OutputStream;\nimport java.net.InetSocketAddress;\nimport java.nio.charset.StandardCharsets;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.concurrent.Executors;\n\n/**\n * HTTP 面（loopback + token）。协议与仓库的 playtest_bridge 对齐：\n *   GET  /status          → 状态 + 能力自报\n *   POST /execute         → {id, action, params} → {id, status, message?, data?}；HTTP 恒 200\n *\n * **安全默认**：只绑 127.0.0.1；端口被占则自增（最多 +20）；除 /status 外一律要 token。\n * **线程纪律**：本类只在 HTTP 线程跑，**绝不碰 MC**；动作全部入队，由客户端 tick 执行。\n */\npublic final class HttpApi {\n    private final PlaytestCore core;\n    private HttpServer server;\n    private int port;\n\n    public HttpApi(PlaytestCore core) { this.core = core; }\n\n    public int start(int preferredPort) throws IOException {\n        IOException last = null;\n        for (int p = preferredPort; p < preferredPort + 20; p++) {\n            try {\n                server = HttpServer.create(new InetSocketAddress(\"127.0.0.1\", p), 0);\n                port = p;\n                break;\n            } catch (IOException e) {\n                last = e;\n            }\n        }\n        if (server == null) throw last == null ? new IOException(\"no port\") : last;\n        server.createContext(\"/status\", this::handleStatus);\n        server.createContext(\"/execute\", this::handleExecute);\n        server.setExecutor(Executors.newSingleThreadExecutor(r -> {\n            Thread t = new Thread(r, \"bandd-playtest-http\");\n            t.setDaemon(true);\n            return t;\n        }));\n        server.start();\n        core.setPort(port);\n        core.evidence().log(\"[QA] http listening on 127.0.0.1:\" + port);\n        return port;\n    }\n\n    public int port() { return port; }\n\n    public void stop() {\n        if (server != null) server.stop(0);\n    }\n\n    private void handleStatus(HttpExchange ex) throws IOException {\n        try {\n            respond(ex, 200, Json.of(core.status()));\n        } catch (Throwable t) {\n            respond(ex, 200, Json.of(PlaytestCore.error(\"STATUS_FAILED\", String.valueOf(t))));\n        }\n    }\n\n    private void handleExecute(HttpExchange ex) throws IOException {\n        Map<String, Object> out;\n        try {\n            String body = new String(readAll(ex), StandardCharsets.UTF_8);\n            Map<String, Object> req = Json.parseObject(body);\n            String id = Json.str(req, \"id\", \"\");\n            String token = Json.str(req, \"token\", header(ex, \"X-Bandd-Token\"));\n            if (core.token() != null && !core.token().isEmpty() && !core.token().equals(token)) {\n                out = PlaytestCore.error(\"UNAUTHORIZED\", \"token 不对或缺失（见 <gameDir>/config/bandd_playtest.json）\");\n            } else {\n                String action = Json.str(req, \"action\", \"\");\n                Map<String, Object> params = new LinkedHashMap<>();\n                Object pv = req.get(\"params\");\n                if (pv instanceof Map) {\n                    @SuppressWarnings(\"unchecked\")\n                    Map<String, Object> pm = (Map<String, Object>) pv;\n                    params = pm;\n                }\n                // 入队 → 等 tick 线程执行（HTTP 线程不碰 MC）\n                ActionQueue.Job job = core.queue().submit(action, params);\n                long budget = core.timeoutMsFor(action);\n                Map<String, Object> res = job.await(budget);\n                if (res == null) {\n                    out = PlaytestCore.error(\"PLAYTEST_TIMEOUT\",\n                            (budget / 1000) + \"s 内未完成（长动作如 open_world 需更久；游戏卡住也会这样）\");\n                } else {\n                    res.put(\"id\", id);\n                    res.put(\"action\", action);\n                    out = res;\n                }\n            }\n        } catch (Throwable t) {\n            out = PlaytestCore.error(\"BAD_REQUEST\", String.valueOf(t));\n        }\n        respond(ex, 200, Json.of(out));\n    }\n\n    private static byte[] readAll(HttpExchange ex) throws IOException {\n        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();\n        byte[] buf = new byte[4096];\n        int n;\n        while ((n = ex.getRequestBody().read(buf)) > 0) bos.write(buf, 0, n);\n        return bos.toByteArray();\n    }\n\n    private static String header(HttpExchange ex, String name) {\n        String v = ex.getRequestHeaders().getFirst(name);\n        return v == null ? \"\" : v;\n    }\n\n    private static void respond(HttpExchange ex, int code, String body) throws IOException {\n        byte[] b = body.getBytes(StandardCharsets.UTF_8);\n        ex.getResponseHeaders().add(\"Content-Type\", \"application/json; charset=utf-8\");\n        ex.sendResponseHeaders(code, b.length);\n        try (OutputStream os = ex.getResponseBody()) {\n            os.write(b);\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/Json.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * 极小 JSON：只做本模组需要的形状。手写、零第三方依赖\n * （仓库里的 driver 也是手写 JSON，不引 Gson —— 见 reference/generators/playtest-driver.ts）。\n */\npublic final class Json {\n    private Json() {}\n\n    public static String esc(String s) {\n        StringBuilder b = new StringBuilder();\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            switch (c) {\n                case '\"':  b.append(\"\\\\\\\"\"); break;\n                case '\\\\': b.append(\"\\\\\\\\\"); break;\n                case '\\n': b.append(\"\\\\n\"); break;\n                case '\\r': b.append(\"\\\\r\"); break;\n                case '\\t': b.append(\"\\\\t\"); break;\n                default:\n                    if (c < 0x20) b.append(String.format(\"\\\\u%04x\", (int) c));\n                    else b.append(c);\n            }\n        }\n        return b.toString();\n    }\n\n    public static String of(Object o) {\n        StringBuilder b = new StringBuilder();\n        write(b, o);\n        return b.toString();\n    }\n\n    @SuppressWarnings(\"unchecked\")\n    private static void write(StringBuilder b, Object o) {\n        if (o == null) { b.append(\"null\"); return; }\n        if (o instanceof String) { b.append('\"').append(esc((String) o)).append('\"'); return; }\n        if (o instanceof Boolean || o instanceof Number) { b.append(o.toString()); return; }\n        if (o instanceof Map) {\n            b.append('{');\n            boolean first = true;\n            for (Map.Entry<String, Object> e : ((Map<String, Object>) o).entrySet()) {\n                if (!first) b.append(',');\n                first = false;\n                b.append('\"').append(esc(e.getKey())).append(\"\\\":\");\n                write(b, e.getValue());\n            }\n            b.append('}');\n            return;\n        }\n        if (o instanceof Iterable) {\n            b.append('[');\n            boolean first = true;\n            for (Object v : (Iterable<Object>) o) {\n                if (!first) b.append(',');\n                first = false;\n                write(b, v);\n            }\n            b.append(']');\n            return;\n        }\n        b.append('\"').append(esc(String.valueOf(o))).append('\"');\n    }\n\n    public static Map<String, Object> parseObject(String s) {\n        Object v = parse(s);\n        if (v instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> m = (Map<String, Object>) v;\n            return m;\n        }\n        return new LinkedHashMap<>();\n    }\n\n    public static Object parse(String s) {\n        P p = new P(s);\n        Object v = p.value();\n        return v;\n    }\n\n    public static String str(Map<String, Object> m, String k, String dflt) {\n        Object v = m.get(k);\n        return v == null ? dflt : String.valueOf(v);\n    }\n\n    public static boolean bool(Map<String, Object> m, String k, boolean dflt) {\n        Object v = m.get(k);\n        if (v instanceof Boolean) return (Boolean) v;\n        if (v instanceof String) return Boolean.parseBoolean((String) v);\n        return dflt;\n    }\n\n    private static final class P {\n        private final String s;\n        private int i;\n\n        P(String s) { this.s = s; }\n\n        void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }\n\n        Object value() {\n            ws();\n            if (i >= s.length()) return null;\n            char c = s.charAt(i);\n            if (c == '{') return obj();\n            if (c == '[') return arr();\n            if (c == '\"') return str();\n            if (s.startsWith(\"true\", i)) { i += 4; return Boolean.TRUE; }\n            if (s.startsWith(\"false\", i)) { i += 5; return Boolean.FALSE; }\n            if (s.startsWith(\"null\", i)) { i += 4; return null; }\n            return num();\n        }\n\n        Map<String, Object> obj() {\n            Map<String, Object> m = new LinkedHashMap<>();\n            i++;\n            ws();\n            if (i < s.length() && s.charAt(i) == '}') { i++; return m; }\n            while (i < s.length()) {\n                ws();\n                String k = str();\n                ws();\n                i++; // ':'\n                m.put(k, value());\n                ws();\n                char c = s.charAt(i++);\n                if (c == '}') return m;\n            }\n            return m;\n        }\n\n        List<Object> arr() {\n            List<Object> l = new ArrayList<>();\n            i++;\n            ws();\n            if (i < s.length() && s.charAt(i) == ']') { i++; return l; }\n            while (i < s.length()) {\n                l.add(value());\n                ws();\n                char c = s.charAt(i++);\n                if (c == ']') return l;\n            }\n            return l;\n        }\n\n        String str() {\n            StringBuilder b = new StringBuilder();\n            i++;\n            while (i < s.length()) {\n                char c = s.charAt(i++);\n                if (c == '\"') return b.toString();\n                if (c == '\\\\') {\n                    char e = s.charAt(i++);\n                    switch (e) {\n                        case 'n': b.append('\\n'); break;\n                        case 't': b.append('\\t'); break;\n                        case 'r': b.append('\\r'); break;\n                        case 'b': b.append('\\b'); break;\n                        case 'f': b.append('\\f'); break;\n                        case 'u':\n                            b.append((char) Integer.parseInt(s.substring(i, i + 4), 16));\n                            i += 4;\n                            break;\n                        default: b.append(e);\n                    }\n                } else {\n                    b.append(c);\n                }\n            }\n            return b.toString();\n        }\n\n        Double num() {\n            int st = i;\n            while (i < s.length() && \"-+.eE0123456789\".indexOf(s.charAt(i)) >= 0) i++;\n            try { return Double.valueOf(s.substring(st, i)); } catch (NumberFormatException e) { return Double.valueOf(0); }\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/PlanInterpreter.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * plan.txt 热载解释器（仓库「游玩自测作业规则」六条铁律的 1/2 条）。\n *\n * 铁律 1（常驻会话）：本解释器是长驻的，守候 evidenceDir/plan.txt；\n *   文件一变就在同一进程内开新一轮，不重启游戏。动作/断言/坐标/等待时长一律改 plan（热载）。\n * 铁律 2（fail-closed + 证据三件）：每轮必落\n *   - state.json（轮末快照）\n *   - exit-code.txt（0 绿 / 1 红）\n *   - qa.log（只含本轮 的 [QA] 段 —— 轮首截断）\n *   外加 rounds.jsonl（每轮一行，含 ok）。\n *\n * DSL（行式；井号起注释；空行忽略）：\n *   wait &lt;ticks&gt;                 等 N 个客户端 tick\n *   press &lt;key&gt; &lt;down|up&gt;      按/松一个逻辑键（受仲裁与「只释放自己按过的键」约束）\n *   hold &lt;key&gt; &lt;ticks&gt;         按住 N tick 后自动松开（记账式）\n *   release                      释放 AI 自己按过的全部键\n *   cmd &lt;rest&gt;                 以玩家身份发命令（禁列 kill/tnt/fill 会被拒 =&gt; 本轮判红）\n *   shot                         截图\n *   mark &lt;name&gt;                记一个标记进 state\n *   assert &lt;field&gt; &lt;op&gt; &lt;value&gt; 类型化后置条件；不成立 =&gt; 本轮判红并停止\n *   stop                         正常结束本轮（绿）\n *\n * field：player.present | player.onGround（布尔）、player.health | pos.x | pos.y | pos.z（数值）、\n *        player.name | screen（字符串，字面 null 表示无界面）\n * op：== != &gt; &lt; &gt;= &lt;=\n */\npublic final class PlanInterpreter {\n    public enum Kind { WAIT, PRESS, HOLD, RELEASE, CMD, SHOT, MARK, ASSERT, STOP,\n                        BOT_SPAWN, BOT_MOVE, BOT_FOLLOW, BOT_DESPAWN }\n\n    public static final class Step {\n        public final Kind kind;\n        public final List<String> args;\n        public final int line;\n        Step(Kind kind, List<String> args, int line) { this.kind = kind; this.args = args; this.line = line; }\n    }\n\n    private final GameBridge bridge;\n    private final EvidenceWriter evidence;\n    private final Path planFile;\n    private final List<Step> steps = new ArrayList<>();\n    private int index = 0;\n    private int waitTicks = 0;\n    private final Map<String, String> holds = new LinkedHashMap<>();\n    private final List<String> marks = new ArrayList<>();\n    private int round = 0;\n    private boolean running = false;\n    private String loadedHash = \"\";\n    private String lastResult = \"none\";\n    private int lastSteps = 0;\n    private int planCheckCounter = 0;\n\n    public PlanInterpreter(GameBridge bridge, EvidenceWriter evidence, Path planFile) {\n        this.bridge = bridge;\n        this.evidence = evidence;\n        this.planFile = planFile;\n    }\n\n    public int round() { return round; }\n    public boolean running() { return running; }\n    public String lastResult() { return lastResult; }\n\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"round\", round);\n        m.put(\"running\", running);\n        m.put(\"stepIndex\", index);\n        m.put(\"stepCount\", steps.size());\n        m.put(\"lastResult\", lastResult);\n        m.put(\"lastSteps\", lastSteps);\n        m.put(\"planFile\", planFile.toString());\n        m.put(\"marks\", new ArrayList<>(marks));\n        return m;\n    }\n\n    /** 客户端 tick 调用（MC 线程）。 */\n    public void tick(PlaytestCore core) {\n        // 每 5 个 tick 看一次 plan.txt（按 tick 计，不依赖墙钟 ⇒ 可确定性测试）\n        if (planCheckCounter++ % 5 == 0) maybeReload(core);\n        if (!running) return;\n        if (waitTicks > 0) {\n            waitTicks--;\n            if (waitTicks == 0 && !holds.isEmpty()) releaseHeld(core, \"hold 到期\");\n            return;\n        }\n        if (index >= steps.size()) { endRound(core, true, \"plan exhausted\"); return; }\n        Step s = steps.get(index);\n        try {\n            if (!exec(core, s)) { endRound(core, false, \"step \" + s.line + \" failed: \" + s.kind); return; }\n        } catch (Throwable t) {\n            evidence.log(\"[QA] step \" + s.line + \" threw: \" + t);\n            endRound(core, false, \"exception at line \" + s.line);\n            return;\n        }\n        index++;\n    }\n\n    /** 文件变了就开新一轮（同一进程内）。 */\n    private void maybeReload(PlaytestCore core) {\n        String text;\n        try {\n            if (!Files.exists(planFile)) return;\n            text = new String(Files.readAllBytes(planFile), StandardCharsets.UTF_8);\n        } catch (IOException e) {\n            return;\n        }\n        String hash = Integer.toHexString(text.hashCode()) + \":\" + text.length();\n        if (hash.equals(loadedHash)) return;\n        loadedHash = hash;\n        steps.clear();\n        String[] lines = text.split(\"\\n\");\n        for (int i = 0; i < lines.length; i++) {\n            Step s = parse(lines[i], i + 1);\n            if (s != null) steps.add(s);\n        }\n        if (running) {\n            evidence.log(\"[QA] plan.txt 变更 => 中断上一轮并开新一轮（同一进程，未重启游戏）\");\n            releaseHeld(core, \"plan reload\");\n        }\n        startRound(core);\n    }\n\n    private Step parse(String raw, int lineNo) {\n        String line = raw;\n        int h = line.indexOf('#');\n        if (h >= 0) line = line.substring(0, h);\n        line = line.trim();\n        if (line.isEmpty()) return null;\n        String[] tok = line.split(\"\\\\s+\", 2);\n        String head = tok[0].toLowerCase();\n        String rest = tok.length > 1 ? tok[1].trim() : \"\";\n        List<String> args = new ArrayList<>();\n        if (!rest.isEmpty()) for (String a : rest.split(\"\\\\s+\")) args.add(a);\n        switch (head) {\n            case \"wait\":    return new Step(Kind.WAIT, args, lineNo);\n            case \"press\":   return new Step(Kind.PRESS, args, lineNo);\n            case \"hold\":    return new Step(Kind.HOLD, args, lineNo);\n            case \"release\": return new Step(Kind.RELEASE, args, lineNo);\n            case \"cmd\":     return new Step(Kind.CMD, java.util.Collections.singletonList(rest), lineNo);\n            case \"shot\":    return new Step(Kind.SHOT, args, lineNo);\n            case \"mark\":    return new Step(Kind.MARK, args, lineNo);\n            case \"assert\":  return new Step(Kind.ASSERT, args, lineNo);\n            case \"stop\":    return new Step(Kind.STOP, args, lineNo);\n            case \"bot_spawn\":   return new Step(Kind.BOT_SPAWN, args, lineNo);\n            case \"bot_move\":    return new Step(Kind.BOT_MOVE, args, lineNo);\n            case \"bot_follow\":  return new Step(Kind.BOT_FOLLOW, args, lineNo);\n            case \"bot_despawn\": return new Step(Kind.BOT_DESPAWN, args, lineNo);\n            default:\n                evidence.log(\"[QA] plan.txt:\" + lineNo + \" 未知指令「\" + head + \"」=> 本轮判红（不静默跳过）\");\n                return new Step(Kind.ASSERT, java.util.Arrays.asList(\"__unknown__\", \"==\", head), lineNo);\n        }\n    }\n\n    private void startRound(PlaytestCore core) {\n        round++;\n        index = 0;\n        waitTicks = 0;\n        holds.clear();\n        marks.clear();\n        running = true;\n        evidence.truncateQaLog();\n        evidence.log(\"[QA] ROUND \" + round + \" START steps=\" + steps.size() + \" plan=\" + planFile);\n        evidence.state(Json.of(core.status()));\n    }\n\n    private void endRound(PlaytestCore core, boolean ok, String reason) {\n        running = false;\n        lastResult = ok ? \"ok\" : \"failed\";\n        lastSteps = index;\n        releaseHeld(core, \"round end\");\n        evidence.exitCode(ok ? 0 : 1);\n        evidence.log(\"[QA] ROUND \" + round + \" DONE ok=\" + ok + \" steps=\" + index + \"/\" + steps.size() + \" reason=\" + reason);\n        Map<String, Object> line = new LinkedHashMap<>();\n        line.put(\"round\", round);\n        line.put(\"ok\", ok);\n        line.put(\"steps\", index);\n        line.put(\"total\", steps.size());\n        line.put(\"reason\", reason);\n        line.put(\"at\", java.time.Instant.now().toString());\n        evidence.appendRounds(Json.of(line));\n        evidence.state(Json.of(core.status()));\n    }\n\n    private void releaseHeld(PlaytestCore core, String why) {\n        for (String k : new ArrayList<>(holds.keySet())) {\n            core.dispatch(\"press\", params(\"key\", k, \"down\", Boolean.FALSE));\n        }\n        holds.clear();\n        core.dispatch(\"release_all\", new LinkedHashMap<>());\n        evidence.log(\"[QA] 释放 AI 按过的键（\" + why + \"）\");\n    }\n\n    private boolean exec(PlaytestCore core, Step s) {\n        switch (s.kind) {\n            case WAIT: {\n                if (s.args.isEmpty()) return false;\n                waitTicks = Integer.parseInt(s.args.get(0));\n                return true;\n            }\n            case PRESS: {\n                if (s.args.size() < 2) return false;\n                boolean down = !\"up\".equalsIgnoreCase(s.args.get(1));\n                Map<String, Object> r = core.dispatch(\"press\", params(\"key\", s.args.get(0), \"down\", down));\n                boolean ok = \"ok\".equals(r.get(\"status\"));\n                if (!ok) evidence.log(\"[QA] press 被拒: \" + r.get(\"code\") + \" \" + r.get(\"message\"));\n                return ok;\n            }\n            case HOLD: {\n                if (s.args.size() < 2) return false;\n                String key = s.args.get(0);\n                Map<String, Object> r = core.dispatch(\"press\", params(\"key\", key, \"down\", Boolean.TRUE));\n                if (!\"ok\".equals(r.get(\"status\"))) { evidence.log(\"[QA] hold 被拒: \" + r.get(\"code\")); return false; }\n                holds.put(key, s.args.get(1));\n                waitTicks = Integer.parseInt(s.args.get(1));\n                return true;\n            }\n            case RELEASE:\n                releaseHeld(core, \"plan 显式 release\");\n                return true;\n            case CMD: {\n                Map<String, Object> r = core.dispatch(\"chat_command\", params(\"command\", s.args.get(0)));\n                boolean ok = \"ok\".equals(r.get(\"status\"));\n                if (!ok) evidence.log(\"[QA] cmd 被拒: \" + r.get(\"code\") + \" \" + r.get(\"message\"));\n                return ok;\n            }\n            case SHOT: {\n                Map<String, Object> r = core.dispatch(\"screenshot\", new LinkedHashMap<>());\n                return \"ok\".equals(r.get(\"status\"));\n            }\n            case MARK: {\n                if (s.args.isEmpty()) return false;\n                marks.add(s.args.get(0));\n                evidence.log(\"[QA] mark \" + s.args.get(0));\n                return true;\n            }\n            case ASSERT: {\n                // 两种写法都收：三段式 <field> <op> <value>，以及两段式 <field> <value>（隐含 ==）\n                if (s.args.size() < 2) return false;\n                String field = s.args.get(0);\n                String op;\n                String want;\n                if (s.args.size() >= 3) {\n                    op = s.args.get(1);\n                    want = s.args.get(2);\n                } else {\n                    op = \"==\";\n                    want = s.args.get(1);\n                }\n                boolean ok = evalAssert(field, op, want);\n                evidence.log(\"[QA] assert \" + field + \" \" + op + \" \" + want + \" -> \" + ok);\n                return ok;\n            }\n            case BOT_SPAWN: {\n                Map<String, Object> q = params(\"name\", s.args.isEmpty() ? \"AI\" : s.args.get(0));\n                if (s.args.size() > 1) q.put(\"distance\", s.args.get(1));\n                return \"ok\".equals(core.dispatch(\"spawn_bot\", q).get(\"status\"));\n            }\n            case BOT_MOVE: {\n                Map<String, Object> q = new LinkedHashMap<>();\n                if (s.args.size() >= 3) {\n                    q.put(\"x\", s.args.get(0));\n                    q.put(\"y\", s.args.get(1));\n                    q.put(\"z\", s.args.get(2));\n                } else {\n                    q.put(\"mode\", \"front\");\n                    if (!s.args.isEmpty()) q.put(\"distance\", s.args.get(0));\n                }\n                return \"ok\".equals(core.dispatch(\"bot_move\", q).get(\"status\"));\n            }\n            case BOT_FOLLOW:\n                return \"ok\".equals(core.dispatch(\"bot_follow\",\n                        params(\"on\", s.args.isEmpty() || !\"off\".equalsIgnoreCase(s.args.get(0)))).get(\"status\"));\n            case BOT_DESPAWN:\n                return \"ok\".equals(core.dispatch(\"bot_despawn\", new LinkedHashMap<>()).get(\"status\"));\n            case STOP:\n                endRound(core, true, \"stop\");\n                return true;\n            default:\n                return false;\n        }\n    }\n\n    /** 类型化后置条件求值（唯一一处读状态的地方）。 */\n    private boolean evalAssert(String field, String op, String want) {\n        if (\"__unknown__\".equals(field)) return false;\n        Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n        Object have;\n        switch (field) {\n            case \"player.present\":  have = st.get(\"present\"); break;\n            case \"player.onGround\": have = st.get(\"onGround\"); break;\n            case \"player.health\":   have = st.get(\"health\"); break;\n            case \"player.name\":     have = st.get(\"name\"); break;\n            case \"screen\":          have = bridge.screenName(); break;\n            case \"pos.x\":           have = st.get(\"x\"); break;\n            case \"pos.y\":           have = st.get(\"y\"); break;\n            case \"pos.z\":           have = st.get(\"z\"); break;\n            default:\n                evidence.log(\"[QA] assert 未知字段「\" + field + \"」=> 判红（不静默通过）\");\n                return false;\n        }\n        if (have == null) return \"null\".equals(want);\n        if (have instanceof Boolean || have instanceof Number) {\n            double h = (have instanceof Boolean) ? (((Boolean) have) ? 1 : 0) : ((Number) have).doubleValue();\n            double w;\n            if (\"true\".equalsIgnoreCase(want)) w = 1;\n            else if (\"false\".equalsIgnoreCase(want)) w = 0;\n            else {\n                try { w = Double.parseDouble(want); } catch (NumberFormatException e) { return false; }\n            }\n            switch (op) {\n                case \"==\": return h == w;\n                case \"!=\": return h != w;\n                case \">\":  return h > w;\n                case \"<\":  return h < w;\n                case \">=\": return h >= w;\n                case \"<=\": return h <= w;\n                default:   return false;\n            }\n        }\n        String h = String.valueOf(have);\n        switch (op) {\n            case \"==\": return h.equals(want);\n            case \"!=\": return !h.equals(want);\n            default:   return false;\n        }\n    }\n\n    private static Map<String, Object> params(Object... kv) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        for (int i = 0; i < kv.length; i += 2) m.put(String.valueOf(kv[i]), kv[i + 1]);\n        return m;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/PlaytestCore.java": "package com.bandd.playtest.core;\n\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * 版本无关的核心：协议 / 动作派发 / 仲裁 / 证据。\n * **不许出现任何 net.minecraft.* 或加载器类型** —— 逐档差异全在 adapter（GameBridge 的实现）。\n */\npublic final class PlaytestCore {\n    /** 仓库口径的禁列（意图菜单禁 kill/tnt/fill）—— 这里对命令级动作也拦一道。 */\n    private static final List<String> FORBIDDEN_PREFIX = Arrays.asList(\"kill\", \"tnt\", \"fill\");\n\n    /** 化身（第二个角色）= 玩家形状的 mannequin 实体（1.21.9+ 起存在；本仓 primer 一手证实）。 */\n    public static final String BOT_TAG = \"bandd_bot\";\n    /** 收回化身的**逐字**命令（禁列 kill 的唯一例外，不接受任何其它形态）。 */\n    public static final String BOT_KILL = \"kill @e[tag=\" + BOT_TAG + \",limit=1]\";\n    private static final String BOT_SELECTOR = \"@e[tag=\" + BOT_TAG + \",limit=1]\";\n\n    private final GameBridge bridge;\n    private final Arbitration arb = new Arbitration();\n    private final ActionQueue queue = new ActionQueue();\n    private final EvidenceWriter evidence;\n    private final PlanInterpreter plan;\n    private final String token;\n    // ---- 化身（第二个角色）状态 ----\n    private boolean botSpawned = false;\n    private boolean botFollow = false;\n    private String botName = \"AI\";\n    private String botKind = \"none\";\n    private final List<String> chatHistory = new ArrayList<>();\n    private int botFollowTick = 0;\n    private final long started = System.currentTimeMillis();\n    private volatile int port = 0;\n    private int requests = 0;\n\n    public PlaytestCore(GameBridge bridge, Path evidenceDir, String token) {\n        this.bridge = bridge;\n        this.evidence = new EvidenceWriter(evidenceDir);\n        this.plan = new PlanInterpreter(bridge, this.evidence, evidenceDir.resolve(\"plan.txt\"));\n        this.token = token;\n    }\n\n    public GameBridge bridge() { return bridge; }\n\n    public Arbitration arbitration() { return arb; }\n\n    public ActionQueue queue() { return queue; }\n\n    public EvidenceWriter evidence() { return evidence; }\n\n    public PlanInterpreter plan() { return plan; }\n\n    /**\n     * **服务端线程**每 tick 调用（由入口挂 ServerTickEvent.Post）。\n     * 为什么单独一个入口：化身是服务端对象，服务端实体的操作必须在**服务端线程**做；\n     * 从客户端 tick 线程去碰它属于跨线程访问（捡拾曾因此静默失效）。\n     */\n    public void onServerTick() {\n        bridge.tickBot();\n    }\n\n    /**\n     * 化身的\"跟随\"：每 20 tick 把 mannequin 放到玩家侧后方 1.5 格。\n     * 说明：化身是 **mannequin**（玩家形状、无连接玩家），移动靠服务端 /tp —— 不是真玩家物理。\n     */\n    private void botFollowStep() {\n        if (!botSpawned || !botFollow) return;\n        if (++botFollowTick % 20 != 0) return;\n        Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n        Object x = st.get(\"x\"), y = st.get(\"y\"), z = st.get(\"z\");\n        if (!(x instanceof Number) || !(y instanceof Number) || !(z instanceof Number)) return;\n        double bx = ((Number) x).doubleValue() + 1.5;\n        double by = ((Number) y).doubleValue();\n        double bz = ((Number) z).doubleValue() + 1.5;\n        bridge.moveBotTo(bx, by, bz);\n    }\n\n    /** 取 x/y/z 三个数字参数；缺任一返回 null。 */\n    private static double[] xyz(Map<String, Object> p) {\n        String x = Json.str(p, \"x\", \"\"), y = Json.str(p, \"y\", \"\"), z = Json.str(p, \"z\", \"\");\n        if (x.isEmpty() || y.isEmpty() || z.isEmpty()) return null;\n        try {\n            return new double[] { Double.parseDouble(x), Double.parseDouble(y), Double.parseDouble(z) };\n        } catch (NumberFormatException e) {\n            return null;\n        }\n    }\n\n    /** tellraw 的 JSON 文本转义（反斜杠与双引号）。 */\n    private static String escJson(String s) {\n        return s.replace(\"\\\\\", \"\\\\\\\\\").replace(\"\\\"\", \"\\\\\\\"\");\n    }\n\n    /** 最近聊天（供 /status 的 chat 段）。 */\n    public List<String> chatHistory() {\n        return new ArrayList<>(chatHistory);\n    }\n\n    private static String round3(double d) {\n        return String.valueOf(Math.round(d * 1000.0) / 1000.0);\n    }\n\n    /** 化身自报（供 /status）。 */\n    public Map<String, Object> botStatus() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"spawned\", botSpawned);\n        m.put(\"name\", botName);\n        m.put(\"kind\", botKind);\n        m.put(\"follow\", botFollow);\n        m.put(\"note2\", \"FakePlayer.tick() 被 NeoForge 置空 ⇒ 捡拾由本模组每 5 tick 显式驱动\");\n        m.put(\"note\", \"fake_player = 服务端假玩家（有物品栏/能破坏放置，但不在 PlayerList、无真实连接）；\"\n                + \"mannequin = 玩家形状化身（无物品栏）\");\n        return m;\n    }\n\n    /**\n     * 每个动作的等待预算（ms）。**真机教训（2026-11-01）**：open_world 读档会阻塞客户端线程\n     * 十余秒 ⇒ 原先一刀切 5s 会把它误报成 PLAYTEST_TIMEOUT（动作其实成功了）。\n     */\n    public long timeoutMsFor(String action) {\n        switch (action) {\n            case \"open_world\": return 90000;\n            case \"screenshot\": return 15000;\n            case \"chat_command\": return 10000;\n            default: return 5000;\n        }\n    }\n\n    public String token() { return token; }\n\n    public void setPort(int p) { this.port = p; }\n\n    /** 客户端 tick 调用（MC 线程）。 */\n    public void onTick() {\n        queue.drain(this);\n        plan.tick(this);\n        botFollowStep();\n        if (arb.mode() == Arbitration.Mode.AUTO && arb.aiOwns() && arb.humanHasControl(bridge)) {\n            arb.yieldToHuman(bridge, \"auto-yield: human input detected\");\n            evidence.log(\"[QA] arbitration AUTO → yield to human（已释放 AI 按下的键）\");\n        }\n    }\n\n    public void onShutdown() {\n        arb.releaseOwned(bridge);\n        evidence.log(\"[QA] shutdown：已释放 AI 按下的全部键\");\n        evidence.exitCode(0);\n    }\n\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"ok\", true);\n        m.put(\"mod\", \"bandd_playtest\");\n        m.put(\"platform\", bridge.platform());\n        m.put(\"mcVersion\", bridge.mcVersion());\n        m.put(\"httpPort\", port);\n        m.put(\"ready\", bridge.ready());\n        m.put(\"tokenRequired\", true);\n        // 能力自报**按适配层自报的缺口过滤**（见 GameBridge#unavailableActions）。\n        // 默认实现返回空 ⇒ 未实现的适配层行为与从前逐字一致。\n        List<String> unavailable = new ArrayList<>(bridge.unavailableActions());\n        List<String> available = new ArrayList<>();\n        for (String a : Capabilities.all()) {\n            if (!unavailable.contains(a)) available.add(a);\n        }\n        m.put(\"actions\", available);\n        m.put(\"actionsUnavailable\", unavailable);\n        Map<String, Object> caps = new LinkedHashMap<>();\n        caps.put(\"bridge\", Capabilities.BRIDGE);\n        caps.put(\"driver\", Capabilities.DRIVER);\n        // driver 面「可用」= 仲裁没禁它 **且** 15 个 driver 动作一个不缺（保守：缺一个就报 false）\n        boolean driverAvailable = arb.mode() != Arbitration.Mode.DUAL;\n        for (String a : Capabilities.DRIVER) {\n            if (unavailable.contains(a)) { driverAvailable = false; break; }\n        }\n        caps.put(\"driverAvailable\", driverAvailable);\n        caps.put(\"supportedKeys\", bridge.supportedKeys());\n        m.put(\"capabilities\", caps);\n        Map<String, Object> a = new LinkedHashMap<>();\n        a.put(\"mode\", arb.mode().name());\n        a.put(\"aiOwns\", arb.aiOwns());\n        a.put(\"yields\", arb.yields());\n        a.put(\"ownedKeys\", arb.ownedCount());\n        a.put(\"lastReason\", arb.lastReason());\n        m.put(\"arbitration\", a);\n        m.put(\"plan\", plan.status());\n        m.put(\"bot\", botStatus());\n        m.put(\"chatCount\", chatHistory.size());\n        m.put(\"evidenceDir\", evidence.dir().toString());\n        m.put(\"uptimeMs\", System.currentTimeMillis() - started);\n        m.put(\"requests\", requests);\n        return m;\n    }\n\n    /** 在 MC 线程上执行一个动作（由 ActionQueue 调用）。 */\n    public Map<String, Object> dispatch(String action, Map<String, Object> p) {\n        requests++;\n        switch (action == null ? \"\" : action) {\n            case \"ping\":\n                return ok(single(\"pong\", Boolean.TRUE));\n            case \"status\":\n                return status();\n            case \"query_player_state\": {\n                Map<String, Object> m = new LinkedHashMap<>();\n                m.put(\"player\", Json.parseObject(bridge.playerStateJson()));\n                m.put(\"screen\", bridge.screenName());\n                return ok(m);\n            }\n            case \"query_screen\":\n                return ok(single(\"screen\", bridge.screenName()));\n            case \"screenshot\": {\n                String path = bridge.screenshotPath();\n                evidence.log(\"[QA] screenshot -> \" + path);\n                return path == null ? error(\"SCREENSHOT_FAILED\", \"适配层返回 null\") : ok(single(\"path\", path));\n            }\n            case \"chat_command\": {\n                String cmd = Json.str(p, \"command\", \"\");\n                if (cmd.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 command\");\n                String head = cmd.startsWith(\"/\") ? cmd.substring(1) : cmd;\n                // 禁列（kill/tnt/fill）默认全禁；**唯一例外**是本模组自己化身的收回，\n                // 且要求**逐字精确匹配**（不是前缀放宽）—— 见 bot_despawn。\n                if (!BOT_KILL.equals(head)) {\n                    for (String bad : FORBIDDEN_PREFIX) {\n                        if (head.startsWith(bad)) return error(\"COMMAND_FORBIDDEN\", \"禁列命令：\" + bad);\n                    }\n                }\n                bridge.chatCommand(cmd);\n                evidence.log(\"[QA] chat_command: \" + cmd);\n                return ok(single(\"sent\", cmd));\n            }\n            case \"query_chat\": {\n                List<String> fresh = bridge.drainChat();\n                chatHistory.addAll(fresh);\n                while (chatHistory.size() > 200) chatHistory.remove(0);\n                return ok(single(\"messages\", fresh));\n            }\n            case \"chat_say\": {\n                String text = Json.str(p, \"text\", \"\");\n                if (text.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 text\");\n                // 用 tellraw 让回复带 [AI] 前缀与颜色（不冒充玩家发言）\n                bridge.chatCommand(\"tellraw @a {\\\"text\\\":\\\"[AI] \" + escJson(text) + \"\\\",\\\"color\\\":\\\"aqua\\\"}\");\n                // 真机发现（2026-11-01）：ClientChatReceivedEvent **只对玩家聊天触发**，tellraw 走系统消息\n                // ⇒ 自己的回话不会回灌进收件箱。这里本地记账，保证对话记录两半边都全（且不产生回声循环）。\n                chatHistory.add(\"ai: \" + text);\n                while (chatHistory.size() > 200) chatHistory.remove(0);\n                evidence.log(\"[QA] chat_say: \" + text);\n                return ok(single(\"said\", text));\n            }\n            case \"press\": {\n                String key = Json.str(p, \"key\", \"\");\n                boolean down = Json.bool(p, \"down\", true);\n                if (!bridge.supportedKeys().contains(key)) {\n                    return error(\"KEY_NOT_SUPPORTED\", \"本档不支持该键：\" + key);\n                }\n                if (arb.mode() == Arbitration.Mode.DUAL) {\n                    return error(\"DRIVER_DISABLED\", \"仲裁模式 DUAL：AI 不碰按键\");\n                }\n                if (down && !arb.aiOwns()) {\n                    return error(\"NOT_OWNING\", \"当前持权方是真人（\" + arb.lastReason() + \"）\");\n                }\n                bridge.setPressed(key, down);\n                arb.noteOwned(key, down);\n                return ok(single(\"key\", key + (down ? \" down\" : \" up\")));\n            }\n            case \"open_world\": {\n                String world = Json.str(p, \"world\", \"\");\n                if (world.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 world（存档名）\");\n                bridge.openWorld(world);\n                evidence.log(\"[QA] open_world: \" + world);\n                return ok(single(\"world\", world));\n            }\n            case \"spawn_bot\": {\n                String name = Json.str(p, \"name\", \"AI\");\n                double dist = 3.0;\n                try { dist = Double.parseDouble(Json.str(p, \"distance\", \"3\")); } catch (NumberFormatException ignored) { }\n                String kind = bridge.spawnBot(name, dist);\n                if (kind == null) return error(\"BOT_UNSUPPORTED\", \"本档或当前环境不支持召唤化身\");\n                botSpawned = true;\n                botName = name;\n                botKind = kind;\n                evidence.log(\"[QA] spawn_bot: \" + name + \" @ \" + kind + \"（前方 \" + dist + \" 格）\");\n                return ok(single(\"bot\", name + \" @ \" + kind));\n            }\n            case \"bot_move\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                String mode = Json.str(p, \"mode\", \"absolute\");\n                if (\"front\".equals(mode)) {\n                    // core 拿不到玩家朝向 ⇒ 只能\"放到玩家旁\"（近似）；要真正\"正前方\"用 spawn_bot。\n                    Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n                    Object px = st.get(\"x\"), py = st.get(\"y\"), pz = st.get(\"z\");\n                    if (!(px instanceof Number) || !(py instanceof Number) || !(pz instanceof Number)) {\n                        return error(\"NO_PLAYER\", \"读不到玩家坐标\");\n                    }\n                    bridge.moveBotTo(((Number) px).doubleValue() + 1.5, ((Number) py).doubleValue(),\n                            ((Number) pz).doubleValue() + 1.5);\n                } else {\n                    String x = Json.str(p, \"x\", \"\"), y = Json.str(p, \"y\", \"\"), z = Json.str(p, \"z\", \"\");\n                    if (x.isEmpty() || y.isEmpty() || z.isEmpty()) {\n                        return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z，或用 mode=front\");\n                    }\n                    try {\n                        bridge.moveBotTo(Double.parseDouble(x), Double.parseDouble(y), Double.parseDouble(z));\n                    } catch (NumberFormatException e) {\n                        return error(\"BAD_REQUEST\", \"x/y/z 必须是数字\");\n                    }\n                }\n                evidence.log(\"[QA] bot_move: \" + mode);\n                return ok(single(\"moved\", mode));\n            }\n            case \"bot_follow\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                botFollow = Json.bool(p, \"on\", true);\n                evidence.log(\"[QA] bot_follow: \" + botFollow);\n                return ok(single(\"follow\", botFollow));\n            }\n            case \"bot_give\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                String item = Json.str(p, \"item\", \"\");\n                if (item.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 item（如 minecraft:diamond）\");\n                int count = 1;\n                try { count = Integer.parseInt(Json.str(p, \"count\", \"1\")); } catch (NumberFormatException ignored) { }\n                String r = bridge.giveBot(item, count);\n                if (r == null) return error(\"GIVE_FAILED\", \"物品 id 不存在或载体不支持：\" + item);\n                evidence.log(\"[QA] bot_give: \" + r);\n                return ok(single(\"gave\", r));\n            }\n            case \"look\": {\n                // 本机玩家转视角（bot_look 是给化身的；真客户端的身体 = mc.player 自己）\n                double ly, lp;\n                try {\n                    ly = Double.parseDouble(Json.str(p, \"yaw\", \"0\"));\n                    lp = Double.parseDouble(Json.str(p, \"pitch\", \"0\"));\n                } catch (NumberFormatException e) {\n                    return error(\"BAD_REQUEST\", \"yaw/pitch 必须是数字\");\n                }\n                if (lp > 90) lp = 90;\n                if (lp < -90) lp = -90;\n                if (!bridge.look(ly, lp)) return error(\"LOOK_UNSUPPORTED\", \"本档未实现本机玩家转视角\");\n                return ok(single(\"look\", ly + \"/\" + lp));\n            }\n            case \"bot_look\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double yaw, pitch;\n                try {\n                    yaw = Double.parseDouble(Json.str(p, \"yaw\", \"0\"));\n                    pitch = Double.parseDouble(Json.str(p, \"pitch\", \"0\"));\n                } catch (NumberFormatException e) {\n                    return error(\"BAD_REQUEST\", \"yaw/pitch 必须是数字\");\n                }\n                if (!bridge.lookBot(yaw, pitch)) return error(\"BOT_UNSUPPORTED\", \"载体不支持转向\");\n                return ok(single(\"look\", yaw + \"/\" + pitch));\n            }\n            case \"bot_break\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double[] c = xyz(p);\n                if (c == null) return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z\");\n                String r = bridge.breakBotBlock(c[0], c[1], c[2]);\n                if (r == null) return error(\"BREAK_FAILED\", \"没挖动（方块不可破坏 / 距离太远 / 载体不支持）\");\n                evidence.log(\"[QA] bot_break: \" + r);\n                return ok(single(\"broke\", r));\n            }\n            case \"bot_place\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double[] c = xyz(p);\n                if (c == null) return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z\");\n                String r = bridge.placeBotBlock(c[0], c[1], c[2]);\n                if (r == null) return error(\"PLACE_FAILED\", \"没放上（手上没有方块 / 目标不可放置 / 载体不支持）\");\n                evidence.log(\"[QA] bot_place: \" + r);\n                return ok(single(\"placed\", r));\n            }\n            case \"set_auth\": {\n                boolean online = Json.bool(p, \"online\", false);\n                if (!bridge.setServerAuth(online)) return error(\"NO_SERVER\", \"本机没有服务端（不在单人/局域网世界里？）\");\n                evidence.log(\"[QA] set_auth: online=\" + online);\n                return ok(single(\"usesAuthentication\", online));\n            }\n            case \"join_server\": {\n                String addr = Json.str(p, \"address\", \"\");\n                if (addr.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 address（如 127.0.0.1:54321）\");\n                bridge.joinServer(addr);\n                evidence.log(\"[QA] join_server: \" + addr);\n                return ok(single(\"connecting\", addr));\n            }\n            case \"open_bot_inventory\": {\n                String how = bridge.openBotInventory();\n                if (how == null) return error(\"BOT_UNSUPPORTED\", \"本档/当前载体不支持把物品栏开到真人屏幕\");\n                evidence.log(\"[QA] open_bot_inventory: \" + how);\n                return ok(single(\"opened\", how));\n            }\n            case \"bot_despawn\": {\n                bridge.despawnBot();\n                botSpawned = false;\n                botFollow = false;\n                evidence.log(\"[QA] bot_despawn（收回化身）\");\n                return ok(single(\"despawned\", Boolean.TRUE));\n            }\n            case \"release_all\":\n                arb.releaseOwned(bridge);\n                return ok(single(\"released\", Boolean.TRUE));\n            case \"take_over\":\n                arb.takeOver();\n                return ok(single(\"aiOwns\", Boolean.TRUE));\n            case \"set_arbitration\": {\n                String mode = Json.str(p, \"mode\", \"\").toUpperCase();\n                try {\n                    arb.setMode(Arbitration.Mode.valueOf(mode));\n                } catch (IllegalArgumentException e) {\n                    return error(\"INVALID_MODE\", \"mode 必须是 AUTO | HOTKEY | DUAL\");\n                }\n                return ok(single(\"mode\", arb.mode().name()));\n            }\n            default:\n                return error(\"UNKNOWN_ACTION\", \"未知动作：\" + action);\n        }\n    }\n\n    // ---- 小工具（core 内部） ----\n\n    public static Map<String, Object> ok(Map<String, Object> data) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"status\", \"ok\");\n        m.put(\"data\", data);\n        return m;\n    }\n\n    public static Map<String, Object> error(String code, String message) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"status\", \"failed\");\n        m.put(\"code\", code);\n        m.put(\"message\", message);\n        return m;\n    }\n\n    public static Map<String, Object> single(String k, Object v) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(k, v);\n        return m;\n    }\n\n    public static List<String> listOf(String... v) {\n        return new ArrayList<>(Arrays.asList(v));\n    }\n}\n",
};

export const PLAYTEST_MOD_CORE_CLASSES: readonly string[] = ["ActionQueue.java","Arbitration.java","Capabilities.java","EvidenceWriter.java","GameBridge.java","HttpApi.java","Json.java","PlanInterpreter.java","PlaytestCore.java"];
